<script setup lang="ts">
import { computed, nextTick, onMounted, onBeforeUnmount, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessageBox } from 'element-plus'
import ReadOnlyDocument from '../components/ReadOnlyDocument.vue'
import TextEvidence from '../components/TextEvidence.vue'
import ImageEvidence from '../components/ImageEvidence.vue'
import OcrEvidence from '../components/OcrEvidence.vue'
import { getSubmission, getSubmissions, stateLabel, decisionLabel, type Snapshot, type Version } from '../api/manuscripts'
import { getFormalReport, decide, retryItem, textEvidence, imageEvidence, qualityText, type Report, type ReportItem } from '../api/review'
import { codePointRangeToEditorRange, type EditorRange } from '../editor/positions'
import type { DocumentNode } from '../types/document'
const route = useRoute(), router = useRouter(), versions = ref<Version[]>([]), selected = ref(''), snapshot = ref<Snapshot>(), report = ref<Report>(), loading = ref(false), error = ref(''), activeTab = ref('TEXT'), selectedImage = ref(''), decision = ref('APPROVE'), reason = ref(''), deciding = ref(false), retrying = ref<string[]>([]), highlights = ref<EditorRange[]>([]), article = ref<HTMLElement>()
const images = computed(() => { const result: Array<{ nodeId: string; fileId: string; caption: string; number: number }> = []; function walk(node: DocumentNode) { if (node.type === 'campusImage') result.push({ nodeId: String(node.attrs?.nodeId), fileId: String(node.attrs?.fileId), caption: String(node.attrs?.caption ?? ''), number: result.length + 1 }); node.content?.forEach(walk) }; if (snapshot.value) walk(snapshot.value.content); return result })
const image = computed(() => images.value.find(item => item.nodeId === selectedImage.value))
const item = computed(() => report.value?.items.find(entry => entry.type === activeTab.value && (entry.type === 'TEXT' || entry.targetKey === selectedImage.value)))
let timer: ReturnType<typeof setTimeout> | undefined, active = true, selection = 0, decisionSignature = '', decisionKey = ''
const retryKeys = new Map<string, string>()
function stop() { if (timer) clearTimeout(timer) }
async function refresh(current = selection) {
  stop(); const version = versions.value.find(entry => entry.submissionId === selected.value); if (!version?.batchId) return
  try { const result = await getFormalReport(version.batchId); if (!active || current !== selection) return; report.value = result; if (['QUEUED', 'RUNNING', 'WAITING_SERVICE'].includes(result.status)) timer = setTimeout(() => refresh(current), 3000) }
  catch (failure) { if (active && current === selection) error.value = failure instanceof Error ? failure.message : '报告读取失败' }
}
async function select() {
  stop(); const current = ++selection; loading.value = true; report.value = undefined; snapshot.value = undefined; highlights.value = []; error.value = ''; reason.value = ''; decision.value = 'APPROVE'
  try { if (route.query.submission !== selected.value) await router.replace({ query: { ...route.query, submission: selected.value } }); const value = await getSubmission(selected.value); if (!active || current !== selection) return; snapshot.value = value; selectedImage.value = images.value[0]?.nodeId ?? ''; await refresh(current) }
  catch (failure) { if (current === selection) error.value = failure instanceof Error ? failure.message : '版本读取失败' } finally { if (current === selection) loading.value = false }
}
async function load() { try { const first = await getSubmission(String(route.params.id)); const history = await getSubmissions(first.manuscriptId); versions.value = history.items; selected.value = history.items.find(entry => entry.submissionId === route.query.submission)?.submissionId ?? first.submissionId; await select() } catch (failure) { error.value = failure instanceof Error ? failure.message : '读取失败' } }
async function locate(start: number, end: number) { if (!snapshot.value?.positionMap) return; try { highlights.value = codePointRangeToEditorRange(snapshot.value.content, snapshot.value.positionMap, start, end); await nextTick(); const target = Array.from(article.value?.querySelectorAll<HTMLElement>('[data-node-id]') ?? []).find(element => element.dataset.nodeId === highlights.value[0]?.nodeId); target?.scrollIntoView({ block: 'center', behavior: 'smooth' }) } catch (failure) { error.value = failure instanceof Error ? failure.message : '定位失败' } }
async function retry(entry: ReportItem) { if (!entry.activeAttemptId || retrying.value.includes(entry.itemId)) return; const signature = `${entry.itemId}:${entry.activeAttemptId}`; if (!retryKeys.has(signature)) retryKeys.set(signature, crypto.randomUUID()); retrying.value.push(entry.itemId); try { await retryItem(entry.itemId, retryKeys.get(signature)!, entry.activeAttemptId); await refresh() } catch (failure) { error.value = failure instanceof Error ? failure.message : '重试失败' } finally { retrying.value = retrying.value.filter(id => id !== entry.itemId) } }
async function submitDecision() {
  if (deciding.value || !snapshot.value) return
  if (decision.value !== 'APPROVE' && !reason.value.trim()) { error.value = '退回或拒绝必须填写理由'; return }
  try { await ElMessageBox.confirm(`确认对第${snapshot.value.versionNo}版作出“${decisionLabel[decision.value]}”决定？`, '人工审核决定', { confirmButtonText: '确认决定', cancelButtonText: '继续审核' }) } catch { return }
  const signature = JSON.stringify({ version: selected.value, decision: decision.value, reason: reason.value }); if (signature !== decisionSignature) { decisionSignature = signature; decisionKey = crypto.randomUUID() }
  deciding.value = true; error.value = ''
  try { await decide(selected.value, decisionKey, decision.value, reason.value); snapshot.value = await getSubmission(selected.value); await refresh() } catch (failure) { error.value = failure instanceof Error ? failure.message : '决定未确认，请重试同次操作' } finally { deciding.value = false }
}
onMounted(load); onBeforeUnmount(() => { active = false; stop() })
</script>
<template><el-alert v-if="error" :title="error" type="error" :closable="false" /><div class="panel history-controls"><RouterLink to="/reviews">返回审核列表</RouterLink><el-select v-model="selected" aria-label="审核版本" :disabled="deciding" @change="select"><el-option v-for="version in versions" :key="version.submissionId" :value="version.submissionId" :label="`第${version.versionNo}版 · ${new Date(version.submittedAt).toLocaleString('zh-CN')}`" /></el-select><span v-if="report">检测{{ stateLabel[report.status] }} · {{ report.completedItems }}/{{ report.totalItems }}项</span><el-button @click="refresh()">刷新报告</el-button></div><div v-loading="loading"><template v-if="snapshot"><div class="review-columns"><section ref="article" class="panel review-document"><div class="section-heading"><h2>送审内容 · 第{{ snapshot.versionNo }}版</h2><el-button v-if="highlights.length" size="small" @click="highlights = []">清除定位</el-button></div><ReadOnlyDocument :document="snapshot" :highlights="highlights" /></section><section class="panel review-evidence"><h2>检测证据</h2><p class="muted">检测仅供人工参考；相似不等于抄袭，未匹配不证明原创。</p><el-tabs v-model="activeTab"><el-tab-pane label="正文" name="TEXT" /><el-tab-pane label="图片相似" name="IMAGE" /><el-tab-pane label="OCR文字" name="OCR_AND_TEXT" /></el-tabs><el-select v-if="activeTab !== 'TEXT' && images.length" v-model="selectedImage" aria-label="证据配图" class="evidence-image-select"><el-option v-for="entry in images" :key="entry.nodeId" :value="entry.nodeId" :label="`配图${entry.number}${entry.caption ? ' · '+entry.caption : ''}`" /></el-select><el-empty v-if="activeTab !== 'TEXT' && !images.length" description="本版没有配图" /><template v-if="item"><div class="section-heading"><span>{{ stateLabel[item.status] }}<template v-if="item.activeAttempt"> · 第{{ item.activeAttempt.attemptNo }}次执行</template></span><el-button v-if="['FAILED','INTERRUPTED'].includes(item.status)" size="small" :loading="retrying.includes(item.itemId)" @click="retry(item)">重试失败项</el-button></div><el-alert v-if="item.activeAttempt?.errorCode" :title="`${item.activeAttempt.errorCode}：${item.activeAttempt.errorMessage}`" type="error" :closable="false" /><TextEvidence v-if="activeTab === 'TEXT' && item.status === 'COMPLETED'" :evidence="textEvidence(item.evidence)" allow-locate @locate="locate" /><ImageEvidence v-if="activeTab === 'IMAGE' && image && item.status === 'COMPLETED'" :evidence="imageEvidence(item.evidence)" :query-file-id="image.fileId" :image-number="image.number" /><template v-if="activeTab === 'OCR_AND_TEXT' && image && item.activeAttempt?.result.ocrStatus"><OcrEvidence :result="item.activeAttempt.result" :file-id="image.fileId" :image-number="image.number" /><TextEvidence v-if="item.activeAttempt.result.textSearchStatus === 'COMPLETED'" :evidence="item.activeAttempt.result.textEvidence ?? []" /></template><p v-if="item.qualityFlags?.length && activeTab !== 'OCR_AND_TEXT'" class="muted">质量标记：{{ qualityText(item.qualityFlags) }}</p><p v-if="['QUEUED','RUNNING'].includes(item.status)" class="muted">处理完成后自动更新</p><p v-if="item.status === 'NOT_APPLICABLE'" class="muted">本项没有适用的输入内容</p></template></section></div><section class="panel"><template v-if="snapshot.decision"><h2>人工决定：{{ decisionLabel[snapshot.decision.decision] }}</h2><p>{{ snapshot.decision.reason || '无补充理由' }}</p><p class="muted">决定时间：{{ new Date(snapshot.decision.decidedAt).toLocaleString('zh-CN') }}；检测继续绑定本版，不改变已作决定。</p></template><template v-else-if="snapshot.lifecycleStatus === 'PENDING'"><h2>人工审核决定</h2><el-radio-group v-model="decision" :disabled="deciding"><el-radio-button value="APPROVE">通过</el-radio-button><el-radio-button value="RETURN">退回</el-radio-button><el-radio-button value="REJECT">拒绝</el-radio-button></el-radio-group><el-input v-model="reason" :disabled="deciding" type="textarea" :rows="3" maxlength="4000" aria-label="审核理由" :placeholder="decision === 'APPROVE' ? '补充说明（可选）' : '请填写退回或拒绝理由（必填）'" class="decision-reason" /><el-button type="primary" :loading="deciding" @click="submitDecision">提交人工决定</el-button></template></section><el-collapse v-if="report"><el-collapse-item title="本批次参考库与方法配置"><p>参考库代：{{ report.libraryGenerationId || '尚未开始' }}</p><pre class="pipeline-config">{{ JSON.stringify(report.pipelineManifest, null, 2) }}</pre></el-collapse-item></el-collapse></template></div></template>
